package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;import org.json.*;
public final class RoadAttributesInstrumentation extends Instrumentation {
 void ok(boolean value,String message){if(!value)throw new AssertionError(message);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{
  File directory=getTargetContext().getFilesDir();byte[] table=Files.readAllBytes(new File(directory,"road-reciprocal.bin").toPath());NativeRoadAttributes helper=new NativeRoadAttributes(ByteBuffer.wrap(table));table[4]^=1;int accepted=0,rejected=0,count;double maximum=0;
  try(DataInputStream in=new DataInputStream(new FileInputStream(new File(directory,"road-attributes.bin")))){ok(in.readInt()==0x3141524e,"Case header");count=in.readInt();ok(count>0&&count<1000000,"Case count");for(int caseIndex=0;caseIndex<count;caseIndex++){int kind=in.readInt(),shift=in.readInt(),height=in.readInt(),affine=in.readInt(),near=in.readInt();double z0=in.readDouble(),z1=in.readDouble();int[] raw={in.readInt(),in.readInt(),in.readInt(),in.readInt()},before=raw.clone();boolean expected=in.readInt()!=0;double u=in.readDouble(),v=in.readDouble(),uv[]={0,0};boolean good=true;
   try{uv=kind==0?helper.vertex(z0,raw,shift,height,affine):helper.near(z0,z1,raw,shift,height,affine,near);}catch(IllegalArgumentException invalid){good=false;}ok(good==expected,"Acceptance case "+caseIndex);ok(Arrays.equals(raw,before),"Input mutation");if(good){accepted++;double[] reference={u,v};for(int k=0;k<2;k++){double error=Math.abs(uv[k]-reference[k]);maximum=Math.max(maximum,error);ok(error<=1e-12*Math.max(1,Math.abs(reference[k])),"UV case "+caseIndex);}}else rejected++;}ok(in.read()==-1,"Trailing cases");}
  JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_ROAD_SOURCE_ATTRIBUTES");report.put("cases",count);report.put("accepted",accepted);report.put("rejected",rejected);report.put("max_uv_difference",maximum);report.put("api",Build.VERSION.SDK_INT);report.put("table_owned_copy",true);report.put("input_immutable",true);report.put("game_steps",0);report.put("gpu_corrected_clipping",false);try(FileOutputStream out=getTargetContext().openFileOutput("road-attributes-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable failure){android.util.Log.e("NFSUGRoadUV","Failed",failure);result.putString("stream","FAIL: "+failure);finish(Activity.RESULT_CANCELED,result);}}
}
